type Order struct {                 // unexported fields: only this package may touch them
    id    OrderID
    lines []OrderLine
    total, limit int64
}
// NewOrder(id, limit) validates and is the only constructor
func (o *Order) AddLine(l OrderLine) error {
    if o.total+l.amount > o.limit { return ErrCreditLimitExceeded }   // the invariant
    o.lines = append(o.lines, l)
    o.total += l.amount
    return nil
}
func (o *Order) Lines() []OrderLine { return slices.Clone(o.lines) }  // no internal slice escapes
